#!/usr/bin/env bash
# Writes dashboard/.env (git-ignored) from infra/main Terraform outputs.
# Usage: scripts/write-dashboard-env.sh
set -euo pipefail

root="$(cd "$(dirname "$0")/.." && pwd)"
out="$root/dashboard/.env"
tf() { terraform -chdir="$root/infra/main" output -raw "$1"; }

umask 077
cat > "$out" <<ENV
# Generated by scripts/write-dashboard-env.sh on $(date -u +%Y-%m-%dT%H:%M:%SZ). Do not commit.
TEMPORAL_NAMESPACE=$(tf namespace_id)
TEMPORAL_ADDRESS=$(tf namespace_endpoint)
TEMPORAL_LOAD_API_KEY=$(tf load_api_key)
TEMPORAL_FAILOVER_API_KEY=$(tf failover_api_key)
GCP_PROJECT_ID=$(tf project_id)
ENV

echo "Wrote $out"
git -C "$root" check-ignore -q "$out" || { echo "ERROR: $out is not git-ignored" >&2; exit 1; }
